import math

def quote(state):
    mid = state['mid_history'][-1] if state['mid_history'] else state['best_bid']
    bid = max(mid - 2, state['best_bid'] - 2)
    ask = min(mid + 2, state['best_ask'] + 2)

    if bid >= ask:
        bid = max(mid - 2, state['best_bid'] - 2)
        ask = min(mid + 2, state['best_ask'] + 2)

    bid_size = min(max(0, state['max_order_size'] - abs(state['inventory'])), state['max_order_size'])
    ask_size = min(max(0, state['max_order_size'] - abs(state['inventory'])), state['max_order_size'])

    if state['inventory'] + bid_size > state['max_inventory']:
        bid_size = state['max_inventory'] - state['inventory']
    if state['inventory'] - ask_size < -state['max_inventory']:
        ask_size = -state['max_inventory'] - state['inventory']

    return {"bid": bid, "bid_size": bid_size, "ask": ask, "ask_size": ask_size}

